#!/usr/bin/env bash
set -euo pipefail

# Safely remove only outputs generated by the CO2 packed-bed workflow.
# Preview is the default.  Actual deletion requires the explicit --yes flag.

if [[ ${1:-} != "--yes" ]]; then
    echo "Preview only. The following generated paths would be removed:"
    find . -maxdepth 1 -type d \( \
        -name 'co2_13x_seed_[0-9]*' -o \
        -name 'paraview_co2_packings' -o \
        -name 'batch_logs_co2_packings' -o \
        -name '-p' \
    \) -print | sort
    find . -maxdepth 1 -type f \( \
        -name 'log.lammps' -o -name 'screen.*' \
    \) -print | sort
    echo
    echo "Run again with --yes to delete exactly these paths."
    exit 0
fi

mapfile -d '' generated_dirs < <(
    find . -maxdepth 1 -type d \( \
        -name 'co2_13x_seed_[0-9]*' -o \
        -name 'paraview_co2_packings' -o \
        -name 'batch_logs_co2_packings' -o \
        -name '-p' \
    \) -print0
)

mapfile -d '' generated_files < <(
    find . -maxdepth 1 -type f \( \
        -name 'log.lammps' -o -name 'screen.*' \
    \) -print0
)

for path in "${generated_dirs[@]}"; do
    case "$path" in
        ./co2_13x_seed_[0-9]*|./paraview_co2_packings|./batch_logs_co2_packings|./-p)
            echo "Removing directory: $path"
            rm -rf -- "$path"
            ;;
        *)
            echo "Refusing unexpected directory: $path" >&2
            exit 2
            ;;
    esac
done

for path in "${generated_files[@]}"; do
    case "$path" in
        ./log.lammps|./screen.*)
            echo "Removing file: $path"
            rm -f -- "$path"
            ;;
        *)
            echo "Refusing unexpected file: $path" >&2
            exit 2
            ;;
    esac
done

echo "CO2 packed-bed generated results removed."
